INSERT INTO `data_nhiem_vu_noi_dung` VALUES
('HD.01','huong_dan','huong_dan','','','','','3:5','...Cháu tỉnh rồi. Đây là Pallet, làng của những Pokémon hiền lành.','Nói chuyện với Xatu ở Pallet','Xatu: ...Cháu tỉnh rồi. Đây là Pallet, làng của những Pokémon hiền lành.|Xatu: Ta là Xatu, trưởng làng. Ta sẽ chỉ cháu những điều đầu tiên.','Xatu: ... Cứ từ từ, nhưng nhớ ghé Xatu nhé.','Xatu: Đi chào Kecleon ở tiệm tạp hoá trước nhé.','Xatu đứng gần quảng trường Pallet.','Thưởng: 1.292 EXP, 323 xu, 2 lượng khoá','','',0,'','',3),
('HD.02','huong_dan','huong_dan','','','','','3:1','Hí hí, khách mới! Tiệm tôi có Thuốc hồi máu và Ether. Hết máu thì ghé nhé.','Nói chuyện với Kecleon ở Pallet','Kecleon: Hí hí, khách mới! Tiệm tôi có Thuốc hồi máu và Ether. Hết máu thì ghé nhé.','Kecleon: Hí hí, Cứ từ từ, nhưng nhớ ghé Kecleon nhé.','Kecleon: Giờ tập đánh một chút. Ra đồng đi bạn nhỏ.','Kecleon đứng gần quảng trường Pallet.','Thưởng: 1.292 EXP, 323 xu, 2 lượng khoá','','',0,'','',3),
('HD.03','huong_dan','huong_dan','','','','','0:2:20','Chạm vào quái để đánh. Hạ 20 Caterpie ngoài đồng.','Hạ 20 Caterpie','Xatu: Chạm vào quái để đánh. Hạ 20 Caterpie ngoài đồng.','Xatu: ... Mới được {da}/20 Caterpie thôi. Cố lên!','Xatu: Giỏi lắm! Lên cấp là mạnh hơn đấy.','Caterpie hay xuất hiện ở Pallet.','Thưởng: 1.735 EXP, 353 xu, 2 lượng khoá','','',0,'','',3),
('HD.04','huong_dan','huong_dan','','','','','3:0','Chan-sey! Máu thấp thì dùng thuốc trong túi nhé. Chị cho em vài bình.','Nói chuyện với Chansey ở Pallet','Chansey: Chan-sey! Máu thấp thì dùng thuốc trong túi nhé. Chị cho em vài bình.','Chansey: Chan-sey! Cứ từ từ, nhưng nhớ ghé Chansey nhé.','Chansey: Nhớ hồi máu trước khi đánh quái mạnh.','Chansey đứng gần quảng trường Pallet.','Thưởng: 1.735 EXP, 353 xu, 2 lượng khoá','','',0,'','',3),
('HD.05','huong_dan','huong_dan','','','','','0:5:20','Dùng chiêu thức (phím tắt) để đánh mạnh hơn. Hạ 20 Ekans.','Hạ 20 Ekans','Xatu: Dùng chiêu thức (phím tắt) để đánh mạnh hơn. Hạ 20 Ekans.','Xatu: ... Mới được {da}/20 Ekans thôi. Cố lên!','Xatu: Chiêu thức hồi chiêu, xen kẽ với đòn thường.','Ekans hay xuất hiện ở Pallet.','Thưởng: 2.370 EXP, 384 xu, 2 lượng khoá','','',0,'','',3),
('HD.06','huong_dan','huong_dan','','','','','3:2','Khà khà! Ta lo đồ đạc. Nâng cấp, chế tạo, khảm ngọc: tìm ta.','Nói chuyện với Machamp ở Pallet','Machamp: Khà khà! Ta lo đồ đạc. Nâng cấp, chế tạo, khảm ngọc: tìm ta.','Machamp: Khà khà! Cứ từ từ, nhưng nhớ ghé Machamp nhé.','Machamp: Mặc thử món đồ ta tặng đi.','Machamp đứng gần quảng trường Pallet.','Thưởng: 2.370 EXP, 384 xu, 2 lượng khoá','','',0,'','',3),
('HD.07','huong_dan','huong_dan','','','','','3:5','Mở túi, chọn món đồ rồi chọn Mặc.','Mặc 1 món trang bị','Xatu: Mở túi, chọn món đồ rồi chọn Mặc.','Xatu: ... Bạn vẫn chưa mặc đồ mới.','Xatu: Ra dáng rồi đấy!','Mở túi đồ, chọn món đồ rồi chọn Mặc.','Thưởng: 3.131 EXP, 383 xu, 2 lượng khoá, Ruy băng sơ cấp','','',0,'','',3),
('HD.08','huong_dan','huong_dan','','','','','0:7:20','Đi xa hơn một chút. Hạ 20 Bellsprout.','Hạ 20 Bellsprout','Xatu: Đi xa hơn một chút. Hạ 20 Bellsprout.','Xatu: ... Mới được {da}/20 Bellsprout thôi. Cố lên!','Xatu: Cháu tiến bộ nhanh lắm.','Bellsprout hay xuất hiện ở Pallet.','Thưởng: 3.131 EXP, 383 xu, 2 lượng khoá','','',0,'','',3),
('HD.09','huong_dan','huong_dan','','','','','','Oáp... mỗi loài cháu gặp sẽ được ghi vào Pokédex. Gặp Ekans đi.','Ghi Ekans vào Pokédex','Xatu: Oáp... mỗi loài cháu gặp sẽ được ghi vào Pokédex. Gặp Ekans đi.','Xatu: ... Chưa gặp Ekans.','Xatu: Sổ có trang đầu tiên rồi.','Chạm trán là ghi được.','Thưởng: 4.269 EXP, 414 xu, 2 lượng khoá','','',0,'','',3),
('HD.10','huong_dan','huong_dan','','','','','3:5','...Cháu đã sẵn sàng. Ngôi sao rơi đêm qua đang chờ cháu tìm hiểu.','Nói chuyện với Xatu ở Pallet','Xatu: ...Cháu đã sẵn sàng. Ngôi sao rơi đêm qua đang chờ cháu tìm hiểu.','Xatu: ... Cứ từ từ, nhưng nhớ ghé Xatu nhé.','Xatu: Đi đi. Ta sẽ dõi theo.','Xatu đứng gần quảng trường Pallet.','Thưởng: 4.269 EXP, 414 xu, 2 lượng khoá','','',0,'','',3),
('C01.1','chinh','chinh','','','','','3:5','Bạn tỉnh dậy giữa đồng cỏ Pallet sau đêm sao băng, không nhớ mình là ai.','Nói chuyện với Xatu ở Pallet','Xatu: ...Ta đã thấy cháu trong giấc mơ đêm qua.|Xatu: Một ngôi sao rơi xuống đồng cỏ, và cháu nằm ngay chỗ nó rơi.|Bạn: Cháu... không nhớ gì cả.|Xatu: Không sao. Ký ức sẽ về khi cháu bước đi.','Xatu: ... Cứ từ từ, nhưng nhớ ghé Xatu nhé.','Xatu: Hãy làm quen với Pallet trước. Snorlax ở cuối làng sẽ cho cháu ăn sáng.','Xatu đứng gần quảng trường Pallet.','Thưởng: 3.230 EXP, 807 xu, 1 lượng khoá','','',0,'','',6),
('C01.2','chinh','chinh','','','','','3:8','Oáp... Xatu bảo có đứa nhỏ rơi từ trời xuống à?','Nói chuyện với Snorlax ở Pallet','Snorlax: Oáp... Xatu bảo có đứa nhỏ rơi từ trời xuống à?|Snorlax: Ăn đi đã, bụng no thì đầu mới sáng.','Snorlax: Oáp... Cứ từ từ, nhưng nhớ ghé Snorlax nhé.','Snorlax: Ngon chứ? Quả Oran vườn ông đấy. Mà... vườn ông đang có chuyện.','Snorlax đứng gần quảng trường Pallet.','Thưởng: 4.038 EXP, 1.009 xu, 2 lượng khoá','','',0,'','',6),
('C01.3','chinh','chinh','','','','','0:1:25','Đám Sandshrew kéo nhau vào gặm hết lá rồi.','Hạ 25 Sandshrew','Snorlax: Đám Sandshrew kéo nhau vào gặm hết lá rồi.|Snorlax: Ông thì... oáp... buồn ngủ quá. Cháu đuổi giúp ông 25 con nhé.','Snorlax: Oáp... Mới được {da}/25 Sandshrew thôi. Cố lên!','Snorlax: Vườn yên rồi! Cháu đánh nhanh hơn ông tưởng. Trong người cháu có lửa đấy.','Sandshrew hay xuất hiện ở Pallet.','Thưởng: 4.038 EXP, 1.009 xu, 2 lượng khoá','','',0,'','',6),
('C01.4','chinh','chinh','','','','','1:0','Mang giỏ Giỏ quả Oran này cho Chansey ở Trung tâm Pokémon.','Giao Giỏ quả Oran cho Chansey','Snorlax: Mang giỏ Giỏ quả Oran này cho Chansey ở Trung tâm Pokémon.|Snorlax: Cô ấy nấu thuốc từ quả của ông.','Snorlax: Oáp... Giỏ quả Oran vẫn trong túi, giao sớm kẻo người ta chờ.','Chansey: Chan-sey! Cảm ơn em. Em bị trầy ở tay rồi kìa, để chị băng cho.','Chansey đang chờ ở Pallet. Hàng nằm trong túi nhiệm vụ.','Thưởng: 4.038 EXP, 1.009 xu, 2 lượng khoá','','',0,'','',6),
('C01.5','chinh','chinh','','1','','ban_kinh_o=3','3:0','Đêm qua cả làng thấy một vệt sáng rơi xuống đồng cỏ phía bắc.','Đứng tại Pallet trên Pallet (ô ?,?)','Chansey: Đêm qua cả làng thấy một vệt sáng rơi xuống đồng cỏ phía bắc.|Chansey: Em thử ra đúng chỗ đó xem, biết đâu nhớ ra điều gì.','Chansey: Chan-sey! Chưa đúng chỗ. Ô ?,? trên Pallet cơ.','Chansey: Bạn đứng giữa vòng cỏ cháy xém. Đất còn ấm, và có thứ gì đó lấp lánh dưới chân.','Mở bản đồ nhỏ, tìm ô ?,?; đứng yên vài giây.','Thưởng: 4.038 EXP, 1.009 xu, 1 lượng khoá','','',0,'','',6),
('C01.6','chinh','chinh','','1','','','2:2:4','Một luồng sáng xanh mờ nhấp nháy trong bụi cỏ.','Tìm Mảnh đá phát sáng giấu ở Pallet','Xatu: Một luồng sáng xanh mờ nhấp nháy trong bụi cỏ.|Xatu: Tìm Mảnh đá phát sáng quanh chỗ đất cháy rồi mang về cho Xatu.','Xatu: ... Vẫn chưa thấy Mảnh đá phát sáng. Để ý chỗ có ánh sáng lạ.','Xatu: ...Đây là mảnh sao. Ta đã thấy nó trong mơ.|Xatu: Mười sáu ngọn đèn, mười sáu mảnh. Và cháu là sợi chỉ nối chúng lại.','Vật ẩn lấp lánh khi bạn đứng gần. Thử các góc khuất của Pallet.','Thưởng: 6.461 EXP, 1.615 xu, 4 lượng khoá, Đai sơ cấp, trang truyện: Chương 1 - Buổi sáng ở Pallet','truyen:Chương 1 - Buổi sáng ở Pallet','',0,'','',6),
('C02.1','chinh','chinh','','','','','3:6','Persian ở đồng cỏ phía bắc mất vòng cổ, và một kẻ giả mạo đang đi khắp làng.','Nói chuyện với Persian ở Pallet','Persian: Hừm. Cưng nhìn ta làm gì? Ta đang rất bực.|Persian: Vòng cổ ngọc của ta biến mất ngay trên đồng cỏ phía bắc!','Persian: Hừm. Cứ từ từ, nhưng nhớ ghé Persian nhé.','Persian: Ai lấy được nó về, ta sẽ... cân nhắc việc cảm ơn.','Persian đứng gần quảng trường Pallet.','Thưởng: 5.927 EXP, 961 xu, 1 lượng khoá','','',0,'','',6),
('C02.2','chinh','chinh','','','','','0:2:25','Đám Caterpie ngoài đồng hay tha đồ lấp lánh về tổ.','Hạ 25 Caterpie','Persian: Đám Caterpie ngoài đồng hay tha đồ lấp lánh về tổ.|Persian: Hạ 25 con, lục tổ của chúng xem.','Persian: Hừm. Mới được {da}/25 Caterpie thôi. Cố lên!','Persian: Không có vòng cổ trong tổ Caterpie. Nhưng có dấu chân... giống hệt dấu chân Persian?','Caterpie hay xuất hiện ở Pallet.','Thưởng: 7.409 EXP, 1.201 xu, 2 lượng khoá','','',0,'','',6),
('C02.3','chinh','chinh','','','','','3:1','Hí hí, bạn nhỏ hỏi đúng người rồi.','Nói chuyện với Kecleon ở Pallet','Kecleon: Hí hí, bạn nhỏ hỏi đúng người rồi.|Kecleon: Sáng nay tôi thấy Persian đi ngang hai lần. Một lần đuôi cong, một lần đuôi... thẳng tưng.','Kecleon: Hí hí, Cứ từ từ, nhưng nhớ ghé Kecleon nhé.','Kecleon: Persian thật không bao giờ để đuôi thẳng. Có kẻ đang đóng giả đấy.','Kecleon đứng gần quảng trường Pallet.','Thưởng: 7.409 EXP, 1.201 xu, 2 lượng khoá','','',0,'','',6),
('C02.4','chinh','chinh','','1','','ban_kinh_o=3','3:1','Kẻ giả mạo hay quay lại bãi cỏ phía bắc lúc vắng người.','Đứng tại Pallet trên Pallet (ô ?,?)','Kecleon: Kẻ giả mạo hay quay lại bãi cỏ phía bắc lúc vắng người.|Kecleon: Đứng chờ ở đó, đừng động đậy nhé.','Kecleon: Hí hí, Chưa đúng chỗ. Ô ?,? trên Pallet cơ.','Kecleon: Một Persian bước ra... rồi hắt xì. Lớp lông vàng tan ra thành khói đen. Đó là một Zorua!','Mở bản đồ nhỏ, tìm ô ?,?; đứng yên vài giây.','Thưởng: 7.409 EXP, 1.201 xu, 2 lượng khoá','','',0,'','',6),
('C02.5','chinh','chinh','','','','','0:5:6','Hô hô, bị phát hiện rồi à? Ta là Lém, bậc thầy hoá trang!','Đánh bại 6 Ekans mạnh','Lém: Hô hô, bị phát hiện rồi à? Ta là Lém, bậc thầy hoá trang!|Lém: Muốn lấy lại vòng cổ thì thắng ta đi. Ta sẽ hoá thành Ekans cho công bằng!','Persian: Hừm. Đối thủ mạnh đấy. Hồi máu rồi đánh tiếp.','Lém: Á á, được rồi, được rồi! Trả này.|Lém: Ta chỉ mượn để đi dự tiệc thôi mà...','Ekans cấp cao hơn bạn vài cấp: mang thuốc theo.','Thưởng: 7.409 EXP, 1.201 xu, 1 lượng khoá','','',0,'','',6),
('C02.6','chinh','chinh','','','','','3:6','Bạn cầm vòng cổ trở về. Persian đang đợi.','Chọn một con đường','Persian: Bạn cầm vòng cổ trở về. Persian đang đợi.|Persian: Bạn sẽ nói gì về Lém?','Persian: Hừm. Persian vẫn chờ câu trả lời của bạn.','Persian: Hừm. Dù cưng chọn thế nào, ta cũng thấy cưng là đứa có lòng.|Persian: Đây, quà của ta. Đừng nói với ai là ta tử tế nhé.','Hai lựa chọn cho danh hiệu khác nhau; không có lựa chọn sai.','Thưởng: 11.854 EXP, 1.922 xu, 4 lượng khoá, Găng đấm sơ cấp, trang truyện: Chương 2 - Đồng cỏ phía bắc, danh hiệu theo lựa chọn','truyen:Chương 2 - Đồng cỏ phía bắc','A:Trả vòng cổ và kể hết sự thật=>danh_hieu:Người ngay thẳng|B:Trả vòng cổ nhưng xin Persian tha cho Lém=>danh_hieu:Người rộng lượng',0,'','',6),
('C03.1','chinh','chinh','','','','','3:1','Xe hàng của Kecleon bị lật trên lối mòn Viridian, hàng hoá vương vãi.','Nói chuyện với Kecleon ở Viridian','Kecleon: Hí hí... à không, hôm nay tôi không cười nổi.|Kecleon: Xe hàng từ Viridian lật giữa đường, đồ rơi khắp lối mòn.','Kecleon: Hí hí, Cứ từ từ, nhưng nhớ ghé Kecleon nhé.','Kecleon: Bạn nhỏ giúp tôi gom lại nhé. Tôi giảm giá cho bạn, hí hí.','Kecleon đứng gần quảng trường Viridian.','Thưởng: 10.673 EXP, 1.035 xu, 1 lượng khoá','','',0,'','',6),
('C03.2','chinh','chinh','','','','','2:6:4','Mấy con Litwick tha mất 5 Gói hàng rồi. Hạ chúng là hàng rơi ra.','Thu 5 Gói hàng (rơi từ Litwick)','Kecleon: Mấy con Litwick tha mất 5 Gói hàng rồi. Hạ chúng là hàng rơi ra.','Kecleon: Hí hí, Có {da}/5 Gói hàng rồi. Còn thiếu một chút.','Kecleon: Đủ cả! À khoan, còn một thùng gỗ nặng nữa, không phải của tôi...','Hạ Litwick ở Viridian, Gói hàng rơi ra thì nhặt.','Thưởng: 13.341 EXP, 1.294 xu, 2 lượng khoá','','',0,'','',6),
('C03.3','chinh','chinh','','2','','','3:1','Đường tới Viridian vắng lắm. Bạn đi trước dò đường giùm tôi.','Đến Viridian','Kecleon: Đường tới Viridian vắng lắm. Bạn đi trước dò đường giùm tôi.','Kecleon: Hí hí, Bạn vẫn chưa đặt chân tới Viridian.','Kecleon: Viridian đây rồi. Gió thổi lá xào xạc, như có ai đang theo sau.','Hỏi Pidgeot ở làng để bay nhanh, hoặc đi bộ theo cổng.','Thưởng: 13.341 EXP, 1.294 xu, 2 lượng khoá','','',0,'','',6),
('C03.4','chinh','chinh','','','','','3:1','Giờ đẩy xe về cửa hàng ở Viridian. Bạn đi kèm, kẻo lại có kẻ phá.','Hộ tống Gói hàng từ Viridian tới Kecleon an toàn','Kecleon: Giờ đẩy xe về cửa hàng ở Viridian. Bạn đi kèm, kẻo lại có kẻ phá.','Kecleon: Hí hí, Hàng vẫn đang trên đường. Đừng để bị cướp!','Kecleon: Về tới nơi an toàn! Bạn nhỏ đúng là ngôi sao may mắn của tôi.','Đi đường lớn, quái có thể chặn đường cướp hàng.','Thưởng: 13.341 EXP, 1.294 xu, 2 lượng khoá','','',0,'','',6),
